local function getURL()
  return vim.fn.input('URL: ', 'http://localhost:5173')
end

-- the actual js files that the browser is executing have to be mapped to the source
-- eg. typescript files before transpiling and bundling have to be mapped to the final browser js
-- the webRoot is used as the base directory for source mappings, the actual mappings include some defaults and some autogenerated by things like vite
local function getWebRoot()
  local root = vim.fs.root(vim.api.nvim_get_current_buf(), {
    { 'vite.config.ts', 'vite.config.js' },
    { 'package.json', 'tsconfig.json', 'jsconfig.json' },
    { 'index.html' },
    { '.git' },
  })

  if root ~= nil then
    return root
  end
  return '${workspaceFolder}'
end

---@module 'dap'
---@type dap.Configuration[]
-- use same configurations for all javascript related filetypes
-- https://codeberg.org/mfussenegger/nvim-dap/wiki/Debug-Adapter-installation#javascript-firefox
-- https://github.com/firefox-devtools/vscode-firefox-debug
local configurations = {
  {
    name = 'Firefox: Launch',
    request = 'launch',
    type = 'firefox',

    reAttach = true,

    url = getURL,
    webRoot = getWebRoot,
  },

  -- Following settings must be changed in firefox's about:config to allow remote debugging
  -- devtools.debugger.remote-enabled = true
  -- devtools.chrome.enabled = true
  -- devtools.prompt-connection = false (recommended)
  -- devtools.debugger.force-local = false (only if you want to allow firefox on one device and editor on another)
  -- Then firefox must be started with the argument -start-debugger-server, and manually navigate to the URL
  {
    name = 'Firefox: Attach',
    request = 'attach',
    type = 'firefox',

    url = getURL,
    webRoot = getWebRoot,
  },
}

---@module 'dap'
---@module 'custom.types.debug-adapter'
---@type debug_adapter_config
return {
  name = 'firefox-debug-adapter',
  mason_name = 'firefox-debug-adapter',

  adapters = {
    firefox = function(callback, _)
      callback {
        type = 'executable',
        command = vim.fn.exepath 'firefox-debug-adapter',
      }
    end,
  },

  configurations = {
    typescriptreact = configurations,
    javascriptreact = configurations,
    typescript = configurations,
    javascript = configurations,
  },
}
